    /** Historical crypto bars for one symbol as canonical {@link marketDataShapes.Bar}s. */
    getCryptoBarsFor(symbol: string, req: Omit<WithTimeframe<WithSymbolList<marketData_2.CryptoBarsRequest>>, "pageToken" | "symbols">, opts?: SymbolCollectOptions): Promise<marketDataShapes_2.Bar[]>;
    /** Historical option bars for one symbol as canonical {@link marketDataShapes.Bar}s. */
