    iterateOptionsContracts(req?: Omit<trading_2.GetOptionsContractsRequest, "pageToken">): AsyncGenerator<trading_2.OptionContract, void, void>;
    /** Collect option contracts into one array. */
    collectOptionsContracts(req?: Omit<trading_2.GetOptionsContractsRequest, "pageToken">): Promise<trading_2.OptionContract[]>;
    /**
     * Iterate account activities across all pages. Activities use cursor
     * pagination: the next `page_token` is the `id` of the last item.
     */
    iterateActivities(req?: Omit<trading_2.GetAccountActivitiesRequest, "pageToken">): AsyncGenerator<trading_2.GetAccountActivities200ResponseInner, void, void>;
    /** Collect account activities across all pages into one array. */
    collectActivities(req?: Omit<trading_2.GetAccountActivitiesRequest, "pageToken">): Promise<trading_2.GetAccountActivities200ResponseInner[]>;
    /** Iterate account activities of a specific type across all pages (cursor). */
    iterateActivitiesByType(req: trading_2.GetAccountActivitiesByActivityTypeRequest): AsyncGenerator<trading_2.GetAccountActivitiesByActivityType200ResponseInner, void, void>;
    /** Collect account activities of a specific type across all pages. */
    collectActivitiesByType(req: trading_2.GetAccountActivitiesByActivityTypeRequest): Promise<trading_2.GetAccountActivitiesByActivityType200ResponseInner[]>;
